#!/usr/bin/env node
/**
 * Tests for the /worklog PowerShell scripts: the engine's pause rules (worklog.ps1) and the only
 * writer of hours (worklog-push.ps1). Zero dependencies — `node:test` on Node 18+, plus pwsh 7.
 *
 *   node --test "tools/*.test.mjs"
 *
 * The engine runs on fabricated transcripts in a temp projects root, dated today so the file filter
 * keeps them. The push runs against an `az` shim first on PATH that keeps CompletedWork in a JSON
 * file and logs every call: no test ever reaches Azure DevOps.
 *
 * Generated by Claude Code at the user's request.
 */

import { test as nodeTest, describe } from 'node:test';
import assert from 'node:assert/strict';
import { spawn, spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, existsSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const SKILL = join(dirname(fileURLToPath(import.meta.url)), '..', 'skills', 'worklog');
const created = [];
process.on('exit', () => {
  for (const dir of created) {
    try { rmSync(dir, { recursive: true, force: true }); } catch { /* tmp, let the OS have it */ }
  }
});
// Tests are collected and run concurrently at the end of the file: each one is a pwsh spawn or more, and
// start-up time dominates, so overlapping them is what keeps the file fast.
const suite = [];
const test = (name, opts, fn) => suite.push([name, opts, fn]);
const tmp = () => { const d = mkdtempSync(join(tmpdir(), 'wls-')); created.push(d); return d; };

const hasPwsh = spawnSync('pwsh', ['-NoProfile', '-Command', '$PSVersionTable.PSVersion.Major'], { encoding: 'utf8' }).status === 0;
const skip = hasPwsh ? false : 'pwsh 7 not on PATH';
const skipWin = !hasPwsh ? 'pwsh 7 not on PATH' : (process.platform === 'win32' ? false : 'az shim is a .cmd');

function pwsh(script, args, env = process.env) {
  return new Promise((resolve) => {
    const child = spawn('pwsh', ['-NoProfile', '-File', join(SKILL, script), ...args], { env });
    let stdout = '';
    let stderr = '';
    child.stdout.setEncoding('utf8').on('data', (d) => { stdout += d; });
    child.stderr.setEncoding('utf8').on('data', (d) => { stderr += d; });
    child.on('error', (e) => resolve({ code: null, out: `${stdout}${stderr}${e.message}` }));
    child.on('close', (code) => resolve({ code, out: `${stdout}${stderr}` }));
  });
}

// ── engine: which gaps are work ─────────────────────────────────────────────────────────────────

const pad = (n) => String(n).padStart(2, '0');
const now = new Date();
const TODAY = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
/** Today at local 10:00 plus `min` minutes, as the transcripts store it (UTC ISO). */
const at = (min) => new Date(now.getFullYear(), now.getMonth(), now.getDate(), 10, min, 0).toISOString();

const ev = (min, type, content, { session = 's1', branch = 'feature/a' } = {}) => ({
  type, timestamp: at(min), sessionId: session, cwd: 'C:\\work\\api', gitBranch: branch,
  message: { role: type, content },
});
const prompt = (min, opts) => ev(min, 'user', 'fai la cosa', opts);
const reply = (min, opts) => ev(min, 'assistant', [{ type: 'text', text: 'fatto' }], opts);
const toolUse = (min, id, input = {}) => ev(min, 'assistant', [{ type: 'tool_use', id, name: 'Bash', input }]);
const toolResult = (min, id) => ev(min, 'user', [{ type: 'tool_result', tool_use_id: id, content: 'ok' }]);

/** Runs the engine on `main` (and optional subagent events) and returns today's active minutes. */
async function activeMinutes(main, sub = []) {
  const root = tmp();
  const proj = join(root, 'C--work-api');
  mkdirSync(join(proj, 's1', 'subagents'), { recursive: true });
  writeFileSync(join(proj, 's1.jsonl'), main.map((e) => JSON.stringify(e)).join('\n'));
  if (sub.length) writeFileSync(join(proj, 's1', 'subagents', 'agent-x.jsonl'), sub.map((e) => JSON.stringify({ ...e, isSidechain: true })).join('\n'));
  const r = await pwsh('worklog.ps1', ['-From', TODAY, '-ProjectsRoot', root, '-OutDir', join(root, 'out')]);
  assert.equal(r.code, 0, r.out);
  const m = r.out.match(/Tempo attivo totale: (?:(\d+)h )?(\d+)m/);
  assert.ok(m, r.out);
  return Number(m[1] || 0) * 60 + Number(m[2]);
}

test('a 30-min gap on the same topic is continuity, not a pause', { skip }, async () => {
  assert.equal(await activeMinutes([prompt(0), reply(1), prompt(31), reply(32)]), 32);
});

test('a 50-min gap with nothing in flight is a pause', { skip }, async () => {
  assert.equal(await activeMinutes([prompt(0), reply(1), prompt(51), reply(52)]), 2);
});

test('a 30-min topic switch with nothing in flight is a pause', { skip }, async () => {
  const b = { session: 's2', branch: 'feature/b' };
  assert.equal(await activeMinutes([prompt(0), reply(1), prompt(31, b), reply(32, b)]), 2);
});

test('a 60-min foreground tool call (a build, a test run) counts', { skip }, async () => {
  assert.equal(await activeMinutes([prompt(0), toolUse(1, 't1'), toolResult(61, 't1'), reply(62)]), 62);
});

test('a subagent working through a 60-min gap counts', { skip }, async () => {
  const sub = Array.from({ length: 13 }, (_, i) => reply(2 + i * 5));   // 10:02 … 11:02
  assert.equal(await activeMinutes([prompt(0), reply(1), prompt(62), reply(63)], sub), 63);
});

test('a background dev server does not stretch a 60-min gap', { skip }, async () => {
  const main = [
    prompt(0), toolUse(1, 'bg1', { run_in_background: true }), toolResult(1, 'bg1'),
    prompt(61), reply(62),
    { type: 'queue-operation', operation: 'enqueue', timestamp: at(90), sessionId: 's1',
      content: '<task-notification><tool-use-id>bg1</tool-use-id></task-notification>' },
  ];
  assert.equal(await activeMinutes(main), 2);
});

// ── engine: -SessionId selects the topics and shows the session's own minutes ───────────────────

/** Runs the engine over `main` with extra flags; returns the whole output. */
async function engine(main, ...flags) {
  const root = tmp();
  const proj = join(root, 'C--work-api');
  mkdirSync(proj, { recursive: true });
  writeFileSync(join(proj, 's1.jsonl'), main.map((e) => JSON.stringify(e)).join('\n'));
  const r = await pwsh('worklog.ps1', ['-From', TODAY, '-ProjectsRoot', root, '-OutDir', join(root, 'out'), ...flags]);
  assert.equal(r.code, 0, r.out);
  return r.out;
}
const total = (out) => out.match(/Tempo attivo totale: ([^|]+)\|/)[1].trim();
const sessionSection = (out) => (out.match(/^Sessione .*(?:\r?\n(?!\r?\n).*)*/m) || [''])[0];

// s1 works on feature/a, s2 on feature/b at the same time: parallel sessions, one timeline each, summed (6m + 6m).
const twoSessions = () => [
  prompt(0), reply(1), prompt(2, { session: 's2', branch: 'feature/b' }), reply(3, { session: 's2', branch: 'feature/b' }),
  prompt(5), reply(6), prompt(7, { session: 's2', branch: 'feature/b' }), reply(8, { session: 's2', branch: 'feature/b' }),
];

test('-SessionId marks only the topics of that session and leaves the active minutes alone', { skip }, async () => {
  const plain = await engine(twoSessions());
  const scoped = await engine(twoSessions(), '-SessionId', 's2');
  assert.doesNotMatch(plain, /^Sessione /m);
  assert.equal(total(scoped), total(plain));
  const sec = sessionSection(scoped);
  assert.match(sec, /feature\/b/);
  assert.doesNotMatch(sec, /feature\/a/);
  assert.match(sec, new RegExp(`${TODAY}.*feature/b +6m`));   // the session's own minutes
  assert.equal(total(plain), '12m');
});

// ── engine: sessions summed, resume dedup, per-session spans ────────────────────────────────────

const withSession = (e, session, uuid) => ({ ...e, sessionId: session, ...(uuid ? { uuid } : {}) });
const tool = (min, id, session) => withSession(toolUse(min, id), session);
const result = (min, id, session) => withSession(toolResult(min, id), session);

test('two overlapping 60-min sessions are summed, not counted once', { skip }, async () => {
  const main = [
    prompt(0), tool(1, 'a1', 's1'), result(61, 'a1', 's1'), reply(62),
    prompt(0, { session: 's2' }), tool(1, 'b1', 's2'), result(61, 'b1', 's2'), reply(62, { session: 's2' }),
  ];
  assert.equal(total(await engine(main)), '2h 4m');
});

// s1 = u1..u4 (10:00-10:03); a resumed s9 copies them (same uuid, same timestamp) then goes on.
const s1Head = () => [prompt(0), reply(1), prompt(2), reply(3)].map((e, i) => withSession(e, 's1', `u${i + 1}`));
const copiesAsS9 = () => s1Head().map((e) => withSession(e, 's9', e.uuid));

test('a resumed transcript counts once: one timeline, and -SessionId of the resume still finds the topic', { skip }, async () => {
  const tail = [withSession(prompt(5), 's9', 'u5'), withSession(reply(6), 's9', 'u6')];
  const out = await engineAt({
    'C--work-api/s1.jsonl': s1Head(),
    'C--work-api/s9.jsonl': [...copiesAsS9(), ...tail],
  }, '-From', TODAY, '-SessionId', 's9');
  const single = await engineAt({ 'C--work-api/s1.jsonl': [...s1Head(), withSession(prompt(5), 's1', 'u5'), withSession(reply(6), 's1', 'u6')] }, '-From', TODAY);
  assert.equal(total(out), total(single));
  assert.equal(total(out), '6m');
  assert.match(sessionSection(out), new RegExp(`${TODAY}.*feature/a +6m`));
});

test('a fork (the original keeps working in parallel) keeps two timelines and drops only the duplicates', { skip }, async () => {
  const out = await engineAt({
    'C--work-api/s1.jsonl': [...s1Head(), withSession(prompt(8), 's1', 'u7'), withSession(reply(10), 's1', 'u8')],
    'C--work-api/s9.jsonl': [...copiesAsS9(), withSession(prompt(6), 's9', 'u5'), withSession(reply(12), 's9', 'u6')],
  }, '-From', TODAY);
  assert.equal(total(out), '16m');   // s1 0-3, 8, 10 = 10m; s9 6, 12 = 6m; one joined timeline would be 12m
});

test('a fork abandoned early keeps the original its own head (the copy ends first)', { skip }, async () => {
  const files = {
    'C--work-api/s1.jsonl': [...s1Head(), withSession(prompt(8), 's1', 'u7'), withSession(reply(12), 's1', 'u8')],
    'C--work-api/s9.jsonl': [...copiesAsS9(), withSession(prompt(5), 's9', 'u5'), withSession(reply(10), 's9', 'u6')],
  };
  const out = await engineAt(files, '-From', TODAY, '-SessionId', 's1');
  assert.equal(total(out), '17m');   // s1 0-3, 8, 12 = 12m; s9 5, 10 = 5m; with the head on s9 s1 would lose the 3->8 gap
  assert.match(sessionSection(out), new RegExp(`${TODAY}.*feature/a +12m`));
});

test('a session idle for 50 min is a pause even while another session works through the gap', { skip }, async () => {
  const main = [
    prompt(0), reply(1), prompt(51), reply(52),
    prompt(0, { session: 's2' }), tool(1, 'b1', 's2'), result(61, 'b1', 's2'), reply(62, { session: 's2' }),
  ];
  assert.equal(total(await engine(main)), '1h 4m');   // s1 2m (its gap is a pause) + s2 62m
});

test('-SessionId on a branch shared with another chat flags it and marks the digest lines of the session', { skip }, async () => {
  const shared = { branch: 'main' };
  const main = [
    prompt(0, shared), reply(1, shared), prompt(2, { ...shared, session: 's2' }), reply(3, { ...shared, session: 's2' }),
    prompt(5, shared), reply(6, shared),
  ];
  const out = await engine(main, '-SessionId', 's1');
  assert.match(sessionSection(out), /main .*\[anche altre sessioni\]/);
  const digest = readFileSync(out.match(/^Digest: (.+)$/m)[1].trim(), 'utf8');
  assert.match(digest, /\| sessione: si/);
  assert.equal(digest.match(/^- \[[^\]]+\] \[S\]/gm).length, 4);   // s1's two prompts and two replies, none of s2's
  assert.doesNotMatch(sessionSection(await engine(twoSessions(), '-SessionId', 's2')), /anche altre sessioni/);
});

test('-SessionId is compared case-insensitively', { skip }, async () => {
  const sec = sessionSection(await engine(twoSessions(), '-SessionId', 'S2'));
  assert.match(sec, /feature\/b/);
  assert.doesNotMatch(sec, /feature\/a/);
});

test('-SessionId with a session absent from the period says so and marks nothing', { skip }, async () => {
  const sec = sessionSection(await engine(twoSessions(), '-SessionId', 'nope'));
  assert.match(sec, /nessun evento/);
  assert.doesNotMatch(sec, /feature\//);
});

// ── engine: -SessionId scope: first day, empty period, digest truncation ────────────────────────

/** `e` moved back by `days` whole days (same local time of day, give or take a DST hour). */
const back = (days, e) => ({ ...e, timestamp: new Date(new Date(e.timestamp).getTime() - days * 86400000).toISOString() });
const dayStr = (days) => {
  const d = new Date(now.getFullYear(), now.getMonth(), now.getDate() - days);
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
};
/** Runs the engine with no -From over `files` ({ 'project-dir/file.jsonl': [events] }). */
async function engineAt(files, ...flags) {
  const root = tmp();
  for (const [rel, events] of Object.entries(files)) {
    mkdirSync(dirname(join(root, rel)), { recursive: true });
    writeFileSync(join(root, rel), events.map((e) => JSON.stringify(e)).join('\n'));
    await new Promise((r) => setTimeout(r, 50));   // distinct, increasing CreationTime: the engine orders fork owners by it
  }
  const r = await pwsh('worklog.ps1', ['-ProjectsRoot', root, '-OutDir', join(root, 'out'), ...flags]);
  assert.equal(r.code, 0, r.out);
  return r.out;
}
const digestOf = (out) => readFileSync(out.match(/^Digest: (.+)$/m)[1].trim(), 'utf8');

test('-SessionId without -From starts at the first day of the session and runs to today', { skip }, async () => {
  const mine = { session: 'AbC-1' };
  const out = await engineAt({
    'C--work-api/AbC-1.jsonl': [back(2, prompt(0, mine)), back(2, reply(1, mine)), prompt(0, mine), reply(1, mine)],
    'C--work-web/other.jsonl': [back(5, prompt(0, { session: 'o1', branch: 'main' })), back(5, reply(1, { session: 'o1', branch: 'main' }))],
  }, '-SessionId', 'abc-1');   // the id differs in case from the file name and the events
  assert.match(out, new RegExp(`^Sessione abc-1: dal ${dayStr(2)}\\r?$`, 'm'));
  assert.match(out, new RegExp(`^=== WORKLOG ${dayStr(2)} -> ${TODAY} ===`, 'm'));
  assert.match(sessionSection(out), new RegExp(`${dayStr(2)}  api / feature/a`));
  assert.match(sessionSection(out), new RegExp(`${TODAY}  api / feature/a`));
  assert.doesNotMatch(out, /web \/ main/);   // the other chat's earlier day is outside the period
});

test('-SessionId with an explicit -From keeps it and prints no derived first day', { skip }, async () => {
  const out = await engineAt({ 'C--work-api/s1.jsonl': [back(2, prompt(0)), back(2, reply(1)), prompt(0), reply(1)] },
    '-SessionId', 's1', '-From', TODAY);
  assert.doesNotMatch(out, /: dal /);
  assert.doesNotMatch(out, new RegExp(dayStr(2)));
});

test('-SessionId with no events in the period says so, not only "Nessuna attivita\'"', { skip }, async () => {
  const out = await engineAt({ 'C--work-api/s1.jsonl': [prompt(0), reply(1)] }, '-SessionId', 's1', '-From', '2020-01-01');
  assert.match(out, /^Sessione s1: nessun evento in questo periodo\.\r?$/m);
  assert.match(out, /Nessuna attivita/);
  const unknown = await engineAt({}, '-SessionId', 'nope');   // no file for the id: nothing to derive, today only
  assert.match(unknown, /^Sessione nope: nessun evento in questo periodo\.\r?$/m);
  assert.doesNotMatch(await engineAt({}, '-From', '2020-01-01'), /^Sessione /m);
});

test('-MaxLinesPerProj never drops the [S] lines nor the "sessione: si" header of the session', { skip }, async () => {
  const b = { session: 's2', branch: 'feature/b' };
  const main = [
    prompt(0), reply(1), prompt(2), reply(3), prompt(4), reply(5),   // feature/a, the busier branch, listed first
    prompt(6, b), reply(7, b), prompt(8, b), reply(9, b),
  ];
  const out = await engine(main, '-SessionId', 's2', '-MaxLinesPerProj', '2');
  const digest = digestOf(out);
  assert.match(digest, /^### topic \(branch\): feature\/b .*\| sessione: si\r?$/m);
  assert.equal(digest.match(/^- \[[^\]]+\] \[S\]/gm).length, 4);   // all of s2's lines, none counted toward the limit
  assert.equal(digest.match(/^- \[[^\]]+\] (?!\[S\])/gm).length, 2);   // feature/a stops at the limit
  assert.match(digest, /righe successive troncate/);
});

test('the raw digest marks "sessione: si" on the branch of the session only', { skip }, async () => {
  const digest = digestOf(await engine(twoSessions(), '-SessionId', 's2'));
  const headers = digest.match(/^### topic \(branch\): .*$/gm);
  assert.equal(headers.length, 2);
  assert.deepEqual(headers.filter((h) => h.includes('sessione: si')).map((h) => h.match(/branch\): (\S+)/)[1]), ['feature/b']);
  assert.doesNotMatch(digestOf(await engine(twoSessions())), /sessione: si/);   // no -SessionId, no marker
});

// ── push: cumulative, idempotent, audited ───────────────────────────────────────────────────────

/** A sandbox: az shim on PATH, CompletedWork state, an empty worklog folder. */
function sandbox(state = { 101: 2 }) {
  const dir = tmp();
  const bin = join(dir, 'bin');
  mkdirSync(bin);
  writeFileSync(join(dir, 'state.json'), JSON.stringify(state));
  writeFileSync(join(bin, 'az-shim.cjs'), `
const fs = require('fs'); const path = require('path');
const dir = path.join(__dirname, '..'); const a = process.argv.slice(2);
fs.appendFileSync(path.join(dir, 'calls.log'), a.join(' ') + '\\n');
const st = JSON.parse(fs.readFileSync(path.join(dir, 'state.json'), 'utf8'));
const id = a[a.indexOf('--id') + 1];
if (!(id in st)) { process.stderr.write('ERROR: work item ' + id + ' not found'); process.exit(1); }
if (a[2] === 'update') {
  const f = a.slice(a.indexOf('--fields') + 1).find((x) => x.startsWith('Microsoft.VSTS.Scheduling.CompletedWork='));
  if (f) st[id] = Number(f.split('=')[1]);
  fs.writeFileSync(path.join(dir, 'state.json'), JSON.stringify(st));
}
process.stdout.write(JSON.stringify({ id: Number(id), fields: { 'Microsoft.VSTS.Scheduling.CompletedWork': st[id] } }));
`);
  writeFileSync(join(bin, 'az.cmd'), '@node "%~dp0az-shim.cjs" %*\r\n');
  const pathKey = Object.keys(process.env).find((k) => k.toLowerCase() === 'path') || 'PATH';
  const env = { ...process.env, [pathKey]: `${bin};${process.env[pathKey]}`, AZ_IDENTITY: '' };
  const push = (rows, ...flags) => {
    const file = join(dir, 'rows.json');
    writeFileSync(file, JSON.stringify(rows));
    return pwsh('worklog-push.ps1', ['-Rows', file, '-OutDir', join(dir, 'wl'), '-ConfigPath', join(dir, 'none.json'), ...flags], env);
  };
  const read = (name) => JSON.parse(readFileSync(join(dir, name), 'utf8'));
  const calls = () => (existsSync(join(dir, 'calls.log')) ? readFileSync(join(dir, 'calls.log'), 'utf8').trim().split('\n') : []);
  return { dir, push, read, calls };
}

const row = (extra = {}) => ({ date: '2026-10-20', org: 'contoso', project: 'P', itemId: 101, hours: 1.5, topic: 'fix cache', ...extra });

test('push adds the delta to CompletedWork and records the period total in the audit', { skip: skipWin }, async () => {
  const sb = sandbox();
  const r = await sb.push([row()]);
  assert.equal(r.code, 0, r.out);
  assert.equal(sb.read('state.json')[101], 3.5);
  const [e] = sb.read('wl/pushed.json');
  assert.equal(e.hoursLogged, 1.5);
  assert.equal(e.periodFrom, '2026-10-20');
  assert.equal(e.mcp, 'cli');
});

test('push re-run of the same row writes nothing; a higher total adds only the difference', { skip: skipWin }, async () => {
  const sb = sandbox();
  await sb.push([row()]);
  const before = sb.calls().length;
  await sb.push([row()]);
  assert.equal(sb.calls().slice(before).filter((c) => c.includes(' update ')).length, 0);
  await sb.push([row({ hours: 2 })]);
  assert.equal(sb.read('state.json')[101], 4);
  assert.equal(sb.read('wl/pushed.json').length, 1);
});

test('push re-run with a minimal row keeps the parent, the created flag and the links', { skip: skipWin }, async () => {
  const sb = sandbox();
  await sb.push([row({ created: true, parentId: 50, prs: [1] })]);
  await sb.push([row()]);
  const [e] = sb.read('wl/pushed.json');
  assert.equal(e.created, true);
  assert.equal(e.parentId, 50);
  assert.deepEqual(e.prs, [1]);
});

test('push honours an explicit delta 0 (hours already logged by hand) and still closes the day', { skip: skipWin }, async () => {
  const sb = sandbox();
  await sb.push([row({ hours: 3, delta: 0 })]);
  assert.equal(sb.read('state.json')[101], 2);
  assert.equal(sb.read('wl/pushed.json')[0].hoursLogged, 3);
});

test('push close and target rows touch only the audit and targets.json', { skip: skipWin }, async () => {
  const sb = sandbox();
  const r = await sb.push([
    { date: '2026-10-13', itemId: null, hours: 0, topic: 'nulla-da-registrare' },
    { date: '2026-10-13', targetHours: 0, note: 'evento' },
  ]);
  assert.equal(r.code, 0, r.out);
  assert.equal(sb.calls().length, 0);
  assert.equal(sb.read('wl/pushed.json')[0].topic, 'nulla-da-registrare');
  assert.deepEqual(sb.read('wl/targets.json').days['2026-10-13'], { hours: 0, note: 'evento' });
});

test('push refuses hours or a delta that is not a multiple of 0.5, and writes nothing for that row', { skip: skipWin }, async () => {
  const sb = sandbox();
  for (const bad of [row({ hours: 1.25 }), row({ hours: 2, delta: 0.3 }), { date: '2026-10-13', itemId: null, hours: 0.75, topic: 'x' }]) {
    const r = await sb.push([bad]);
    assert.equal(r.code, 1, JSON.stringify(bad));
    assert.match(r.out, /multipl/);
  }
  assert.equal(sb.read('state.json')[101], 2);
  assert.ok(!existsSync(join(sb.dir, 'wl', 'pushed.json')));
});

test('push -DryRun calls nothing and writes nothing', { skip: skipWin }, async () => {
  const sb = sandbox();
  const r = await sb.push([row(), { date: '2026-10-13', targetHours: 0 }], '-DryRun');
  assert.equal(r.code, 0, r.out);
  assert.equal(sb.calls().length, 0);
  assert.ok(!existsSync(join(sb.dir, 'wl', 'pushed.json')));
  assert.ok(!existsSync(join(sb.dir, 'wl', 'targets.json')));
});

test('push: a failing item exits 1 and leaves its audit entry unwritten, the others go through', { skip: skipWin }, async () => {
  const sb = sandbox();
  const r = await sb.push([row({ itemId: 999 }), row()]);
  assert.equal(r.code, 1);
  assert.match(r.out, /ERRORE/);
  const audit = sb.read('wl/pushed.json');
  assert.deepEqual(audit.map((e) => e.itemId), [101]);
});

describe('worklog scripts', { concurrency: 4 }, () => {
  for (const [name, opts, fn] of suite) nodeTest(name, opts, fn);
});
